# Builds rex-strength-lab/research/reviews/canon-5-round1.json from the round's raw findings (verified_ok, findings and verdicts
# kept as given), with each finding's outcome; the revert and mutant results are read from ../revert1-results.json.
import json, os, sys
HERE = os.path.dirname(os.path.abspath(__file__))
raw = json.load(open(os.path.join(HERE, '..', '..', 'round1-raw.json')))
R = json.load(open(os.path.join(HERE, '..', 'revert1-results.json')))
X = json.load(open(os.path.join(HERE, '..', 'rec1-facts.json')))   # timings and counts measured after the fixes
def res(name):
    r = R[name]
    if 'error' in r: return name + ': ERROR ' + r['error']
    return name + ' -> ' + ('fails ' + '; '.join(f[:70] for f in r['fails']) if r['killed'] else 'SURVIVES')
def many(prefix): return '; '.join(res(n) for n in R if n.startswith(prefix))
