out = {'round': 1, 'what': X['what'], 'script': 'workflow canon-review (args {pr: 5, round: 1, lenses: [design, copy, code]}); kept in history at the end of the run', 'counts': {'findings': 11, 'confirmed': 9, 'refuted': ['design-flicker-word-vs-car-crash', 'copy-6'], 'no_verdict': [], 'reports': 13, 'merged': [['design-unbounded-no-physical-answer', 'copy-3'], ['code-2', 'code-3']]}, 'lenses': []}
n = 0
for L in raw:
    lens = {'lens': L['lens'], 'verified_ok': L['verified_ok'], 'findings': []}
    for f in L['findings']:
        g = dict(f); g['outcome'] = OUT[f['id']]; lens['findings'].append(g); n += 1
    out['lenses'].append(lens)
assert n == 13 and all(f['id'] in OUT for L in raw for f in L['findings'])
dst = '/home/user/rex-strength-lab/rex-strength-lab/research/reviews/canon-5-round1.json'
json.dump(out, open(dst, 'w', encoding='utf-8'), indent=1, ensure_ascii=False); open(dst, 'a').write('\n')
print('wrote', dst)
